import os, re
ROOT = r"D:\repository"
def grep_file(fp, pats):
    if not os.path.isfile(fp):
        return "FILE-MISSING: " + fp
    rx = {p: re.compile(re.escape(p)) for p in pats}
    found = {p: [] for p in pats}
    with open(fp, encoding="utf-8", errors="ignore") as f:
        for ln, line in enumerate(f, 1):
            for p, r in rx.items():
                if r.search(line) and len(found[p]) < 3:
                    found[p].append("%d|%s" % (ln, line.strip()[:110]))
    return "; ".join("[%s]=%s" % (p, found[p] if found[p] else "MISS") for p in pats)

def walk_grep(root, pats, ext={".vue",".js",".ts",".json"}, skip={"node_modules",".git","dist","unpackage"}):
    rx = {p: re.compile(re.escape(p)) for p in pats}
    found = {p: [] for p in pats}
    for dp, dns, fns in os.walk(root):
        dns[:] = [d for d in dns if d not in skip and not d.startswith(".")]
        for fn in fns:
            if os.path.splitext(fn)[1] not in ext: continue
            fp = os.path.join(dp, fn)
            try:
                with open(fp, encoding="utf-8", errors="ignore") as f:
                    for ln, line in enumerate(f, 1):
                        for p, r in rx.items():
                            if r.search(line) and len(found[p]) < 4:
                                found[p].append(os.path.relpath(fp, ROOT)+":%d|%s"%(ln,line.strip()[:90]))
            except Exception: pass
    return "; ".join("[%s]=%s"%(p, found[p] if found[p] else "MISS") for p in pats)

